int binarySearch(const vector<int>& a, int target) {
    int lo = 0, hi = (int)a.size() - 1;
    while (lo <= hi) {
        int mid = lo + (hi - lo) / 2;      // never lo+hi: that can overflow
        if (a[mid] == target) return mid;
        if (a[mid] < target) lo = mid + 1;
        else                 hi = mid - 1;
    }
    return -1;
}

int bsRec(const vector<int>& a, int target, int lo, int hi) {
    if (lo > hi) return -1;                // empty range: not found
    int mid = lo + (hi - lo) / 2;
    if (a[mid] == target) return mid;
    return a[mid] < target ? bsRec(a, target, mid + 1, hi)
                           : bsRec(a, target, lo, mid - 1);
}

