def binary_search(a: list[int], target: int) -> int:
    lo, hi = 0, len(a) - 1
    while lo <= hi:
        mid = lo + (hi - lo) // 2      # never (lo+hi): that can overflow in C++
        if a[mid] == target:
            return mid
        if a[mid] < target:
            lo = mid + 1
        else:
            hi = mid - 1
    return -1


def bs_rec(a: list[int], target: int, lo: int = 0, hi: int = None) -> int:
    if hi is None:
        hi = len(a) - 1
    if lo > hi:
        return -1                      # empty range: not found
    mid = lo + (hi - lo) // 2
    if a[mid] == target:
        return mid
    return (bs_rec(a, target, mid + 1, hi) if a[mid] < target
            else bs_rec(a, target, lo, mid - 1))

