int guessNumber(int n) {
    int lo = 1, hi = n;
    while (lo <= hi) {
        int mid = lo + (hi - lo) / 2;
        int r = guess(mid);
        if (r == 0) return mid;
        if (r == 1) lo = mid + 1;      // my guess was too low
        else        hi = mid - 1;      // my guess was too high
    }
    return -1;
}

