pair<int,int> searchRange(const vector<int>& a, int target) {
    auto hunt = [&](bool wantFirst) {
        int lo = 0, hi = (int)a.size() - 1, found = -1;
        while (lo <= hi) {
            int mid = lo + (hi - lo) / 2;
            if (a[mid] == target) {
                found = mid;                       // record, then keep hunting
                if (wantFirst) hi = mid - 1;       // earlier match may exist
                else           lo = mid + 1;       // later match may exist
            }
            else if (a[mid] < target) lo = mid + 1;
            else                      hi = mid - 1;
        }
        return found;
    };
    return {hunt(true), hunt(false)};
}

