int mySqrt(int x) {
    if (x < 2) return x;                      // 0 and 1 are their own roots
    int lo = 1, hi = x / 2 + 1, ans = 1;
    while (lo <= hi) {
        int mid = lo + (hi - lo) / 2;
        if ((long long)mid * mid <= x) {      // long long: mid*mid overflows int
            ans = mid;                        // feasible: remember and try bigger
            lo = mid + 1;
        } else {
            hi = mid - 1;
        }
    }
    return ans;
}

