// Each element sits at most one position from its sorted home.
int searchNearlySorted(const vector<int>& a, int target) {
    int lo = 0, hi = (int)a.size() - 1;
    while (lo <= hi) {
        int mid = lo + (hi - lo) / 2;
        if (a[mid] == target) return mid;
        if (mid - 1 >= lo && a[mid - 1] == target) return mid - 1;
        if (mid + 1 <= hi && a[mid + 1] == target) return mid + 1;
        // skip TWO past mid, since mid+-1 are already ruled out
        if (a[mid] < target) lo = mid + 2;
        else                 hi = mid - 2;
    }
    return -1;
}

