// Returns the index, and fills 'trace' with the (lo,hi,mid) of every frame.
int bsTrace(const vector<int>& a, int target, int lo, int hi,
            vector<array<int,3>>& trace) {
    if (lo > hi) return -1;
    int mid = lo + (hi - lo) / 2;
    trace.push_back({lo, hi, mid});
    if (a[mid] == target) return mid;
    return a[mid] < target ? bsTrace(a, target, mid + 1, hi, trace)
                           : bsTrace(a, target, lo, mid - 1, trace);
}

