def bs_trace(a: list[int], target: int, lo: int = 0, hi: int = None,
             trace: list = None) -> tuple:
    """Returns (index, trace) where trace lists (lo, hi, mid) per frame."""
    if hi is None:
        hi, trace = len(a) - 1, []
    if lo > hi:
        return -1, trace
    mid = lo + (hi - lo) // 2
    trace.append((lo, hi, mid))
    if a[mid] == target:
        return mid, trace
    if a[mid] < target:
        return bs_trace(a, target, mid + 1, hi, trace)
    return bs_trace(a, target, lo, mid - 1, trace)

