// Every element appears twice, adjacent, except one. Array is sorted.
int singleNonDuplicate(const vector<int>& a) {
    int lo = 0, hi = (int)a.size() - 1;
    while (lo < hi) {
        int mid = lo + (hi - lo) / 2;
        // mid^1 is mid's partner: 0<->1, 2<->3, 4<->5, ...
        if (a[mid] == a[mid ^ 1]) lo = mid + 1;   // pairing intact: break is right
        else                      hi = mid;       // pairing broken: answer is at or left
    }
    return a[lo];
}

