def single_non_duplicate(a: list[int]) -> int:
    """Every element appears twice, adjacent, except one. Array is sorted."""
    lo, hi = 0, len(a) - 1
    while lo < hi:
        mid = lo + (hi - lo) // 2
        # mid^1 is mid's partner: 0<->1, 2<->3, 4<->5, ...
        if a[mid] == a[mid ^ 1]:
            lo = mid + 1        # pairing intact: the break is to the right
        else:
            hi = mid            # pairing broken: answer is at or left of mid
    return a[lo]
